INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q1', 'analyse-fondamentale', 'intro', 1, 'L''analyse fondamentale cherche à déterminer :', '[{"id":"a","label":"La tendance technique du marché"},{"id":"b","label":"La valeur intrinsèque d''un actif"},{"id":"c","label":"Les volumes de transactions"},{"id":"d","label":"La volatilité future"}]'::jsonb, 'b', 'Elle se base sur les facteurs économiques et financiers pour évaluer la « juste valeur ».', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q2', 'analyse-fondamentale', 'intro', 1, 'Selon l''analyse fondamentale, le prix de marché :', '[{"id":"a","label":"Coïncide toujours avec la valeur intrinsèque"},{"id":"b","label":"Peut s''écarter temporairement de la valeur intrinsèque"},{"id":"c","label":"Est indépendant des fondamentaux"},{"id":"d","label":"Détermine la valeur intrinsèque"}]'::jsonb, 'b', 'Les marchés ne sont pas parfaitement efficients ; des divergences apparaissent.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q3', 'analyse-fondamentale', 'intro', 1, 'Un des principes clés de l''analyse fondamentale est :', '[{"id":"a","label":"L''efficience absolue des marchés"},{"id":"b","label":"Le retour à la moyenne à long terme"},{"id":"c","label":"L''absence de risque"},{"id":"d","label":"L''analyse des seuls graphiques"}]'::jsonb, 'b', 'On s''attend à ce que le prix converge vers la valeur intrinsèque à long terme.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q4', 'analyse-fondamentale', 'intro', 1, 'L''analyse fondamentale est particulièrement utile pour :', '[{"id":"a","label":"Le trading haute fréquence"},{"id":"b","label":"Les stratégies d''investissement à long terme"},{"id":"c","label":"La détection de supports/résistances"},{"id":"d","label":"L''analyse des chandeliers"}]'::jsonb, 'b', 'Elle se concentre sur les moteurs de valeur sur la durée.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q5', 'analyse-fondamentale', 'intro', 1, 'Lequel n''est PAS un objectif de l''analyse fondamentale ?', '[{"id":"a","label":"Identifier les actifs surévalués"},{"id":"b","label":"Comprendre les moteurs du marché"},{"id":"c","label":"Prédire le prix à 5 minutes"},{"id":"d","label":"Gérer les risques"}]'::jsonb, 'c', 'L''AF n''a pas vocation à prévoir les mouvements de très court terme.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q6', 'analyse-fondamentale', 'intro', 2, 'La valeur intrinsèque repose sur :', '[{"id":"a","label":"Les rumeurs de marché"},{"id":"b","label":"Les facteurs économiques, financiers et qualitatifs"},{"id":"c","label":"Le sentiment des investisseurs"},{"id":"d","label":"Les ordres de bourse"}]'::jsonb, 'b', 'Elle est basée sur une analyse approfondie des fondamentaux.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q7', 'analyse-fondamentale', 'intro', 2, 'L''hypothèse d''efficience des marchés est :', '[{"id":"a","label":"Totalement vraie dans tous les cas"},{"id":"b","label":"Remise en cause par l''analyse fondamentale"},{"id":"c","label":"Sans importance pour l''investisseur"},{"id":"d","label":"Une loi mathématique"}]'::jsonb, 'b', 'L''analyse fondamentale postule que les marchés ne sont pas toujours efficients.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q8', 'analyse-fondamentale', 'intro', 2, 'Le principe de « retour à la moyenne » implique que :', '[{"id":"a","label":"Les prix ne reviennent jamais à leur moyenne"},{"id":"b","label":"Les prix tendent à revenir vers leur valeur intrinsèque"},{"id":"c","label":"La moyenne est toujours inférieure au prix"},{"id":"d","label":"Le prix moyen est la seule référence"}]'::jsonb, 'b', 'C''est l''un des piliers de l''analyse fondamentale.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q9', 'analyse-fondamentale', 'intro', 1, 'L''analyse fondamentale s''oppose à l''analyse technique car :', '[{"id":"a","label":"Elle utilise des graphiques"},{"id":"b","label":"Elle s''intéresse aux causes sous-jacentes"},{"id":"c","label":"Elle est moins fiable"},{"id":"d","label":"Elle ne s''applique qu''aux actions"}]'::jsonb, 'b', 'L''AT se concentre sur les prix et volumes, l''AF sur les fondamentaux.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q10', 'analyse-fondamentale', 'intro', 1, 'Un investisseur qui utilise l''analyse fondamentale cherche à :', '[{"id":"a","label":"Profiter des fluctuations de très court terme"},{"id":"b","label":"Exploiter les écarts entre prix et valeur intrinsèque"},{"id":"c","label":"Suivre les tendances des graphiques"},{"id":"d","label":"Ignorer les données économiques"}]'::jsonb, 'b', 'L''objectif est d''acheter sous-évalué et vendre surévalué.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q11', 'analyse-fondamentale', 'intro', 1, 'La « valeur intrinsèque » d''une devise dépend notamment :', '[{"id":"a","label":"Des ordres de bourse"},{"id":"b","label":"De la santé économique du pays émetteur"},{"id":"c","label":"Du nombre de transactions"},{"id":"d","label":"De la météo"}]'::jsonb, 'b', 'La santé économique (PIB, inflation, etc.) détermine la valeur d''une devise.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q12', 'analyse-fondamentale', 'intro', 2, 'Pourquoi l''analyse fondamentale est-elle importante pour la gestion des risques ?', '[{"id":"a","label":"Elle permet d''éviter toute perte"},{"id":"b","label":"Elle identifie les actifs soutenus par des fondamentaux solides"},{"id":"c","label":"Elle garantit des rendements élevés"},{"id":"d","label":"Elle est sans risque"}]'::jsonb, 'b', 'En connaissant la solidité des fondamentaux, on peut mieux évaluer le risque.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q13', 'analyse-fondamentale', 'intro', 3, 'L''analyse fondamentale est particulièrement adaptée aux marchés :', '[{"id":"a","label":"Peu liquides"},{"id":"b","label":"Où les prix sont toujours justes"},{"id":"c","label":"Où des inefficiences peuvent exister"},{"id":"d","label":"Où l''information est parfaite"}]'::jsonb, 'c', 'Les inefficiences créent des opportunités pour l''AF.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q14', 'analyse-fondamentale', 'intro', 3, 'La valeur intrinsèque d''une entreprise est souvent estimée via :', '[{"id":"a","label":"Les cours de bourse"},{"id":"b","label":"Les flux de trésorerie futurs actualisés"},{"id":"c","label":"Les volumes de transactions"},{"id":"d","label":"Les rumeurs"}]'::jsonb, 'b', 'Le modèle DCF est l''un des plus utilisés.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.1-Q15', 'analyse-fondamentale', 'intro', 3, 'Dans l''analyse fondamentale, la « convergence vers la valeur intrinsèque » :', '[{"id":"a","label":"Est instantanée"},{"id":"b","label":"Peut prendre du temps"},{"id":"c","label":"N''arrive jamais"},{"id":"d","label":"Dépend des algorithmes"}]'::jsonb, 'b', 'Les marchés peuvent rester irrationnels longtemps.', true);

INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q1', 'analyse-fondamentale', 'macro', 1, 'Une hausse surprise du PIB américain est généralement :', '[{"id":"a","label":"Négative pour l''USD"},{"id":"b","label":"Positive pour l''USD"},{"id":"c","label":"Neutre"},{"id":"d","label":"Impossible à anticiper"}]'::jsonb, 'b', 'Une croissance robuste attire les capitaux et peut maintenir les taux élevés.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q2', 'analyse-fondamentale', 'macro', 1, 'L''indicateur qui mesure l''évolution des prix à la consommation est :', '[{"id":"a","label":"Le PIB"},{"id":"b","label":"Le NFP"},{"id":"c","label":"L''IPC (CPI)"},{"id":"d","label":"Le PMI"}]'::jsonb, 'c', 'L''Indice des Prix à la Consommation est la mesure standard de l''inflation.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q3', 'analyse-fondamentale', 'macro', 1, 'Des taux d''intérêt plus élevés tendent à :', '[{"id":"a","label":"Faire fuir les capitaux étrangers"},{"id":"b","label":"Attirer les capitaux étrangers"},{"id":"c","label":"Ne pas affecter la devise"},{"id":"d","label":"Réduire l''inflation immédiatement"}]'::jsonb, 'b', 'Les investisseurs recherchent de meilleurs rendements, augmentant la demande pour la devise.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q4', 'analyse-fondamentale', 'macro', 1, 'Un excédent commercial (exportations > importations) signifie :', '[{"id":"a","label":"Une demande plus faible pour la devise nationale"},{"id":"b","label":"Une demande plus forte pour la devise nationale"},{"id":"c","label":"Une dépréciation automatique"},{"id":"d","label":"Aucun impact sur le forex"}]'::jsonb, 'b', 'Les acheteurs étrangers ont besoin de la devise pour payer les exportations.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q5', 'analyse-fondamentale', 'macro', 1, 'Les NFP (Non-Farm Payrolls) mesurent :', '[{"id":"a","label":"Le nombre d''emplois dans l''agriculture"},{"id":"b","label":"Le nombre d''emplois créés hors secteur agricole"},{"id":"c","label":"Le taux de chômage uniquement"},{"id":"d","label":"Les salaires horaires moyens"}]'::jsonb, 'b', 'Les NFP mesurent le nombre d''emplois créés ou perdus dans le secteur non agricole.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q6', 'analyse-fondamentale', 'macro', 2, 'Une inflation élevée et persistante peut conduire la banque centrale à :', '[{"id":"a","label":"Baisser ses taux directeurs"},{"id":"b","label":"Augmenter ses taux directeurs"},{"id":"c","label":"Ne rien changer"},{"id":"d","label":"Acheter des obligations"}]'::jsonb, 'b', 'La politique restrictive (hausse des taux) vise à réduire l''inflation.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q7', 'analyse-fondamentale', 'macro', 2, 'Parmi les indicateurs suivants, lequel est un indicateur avancé (leading) ?', '[{"id":"a","label":"Taux de chômage"},{"id":"b","label":"PIB"},{"id":"c","label":"Permis de construire"},{"id":"d","label":"IPC"}]'::jsonb, 'c', 'Les permis de construire changent avant que l''économie ne suive une tendance.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q8', 'analyse-fondamentale', 'macro', 2, 'Lequel de ces indicateurs est un indicateur coïncident ?', '[{"id":"a","label":"Spread de taux (inversion courbe)"},{"id":"b","label":"Production industrielle"},{"id":"c","label":"Coûts unitaires main-d''œuvre"},{"id":"d","label":"Nouvelles commandes équipement"}]'::jsonb, 'b', 'La production industrielle évolue approximativement en même temps que l''économie.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q9', 'analyse-fondamentale', 'macro', 2, 'Le taux de chômage est considéré comme un indicateur :', '[{"id":"a","label":"Avancé"},{"id":"b","label":"Coïncident"},{"id":"c","label":"Retardé"},{"id":"d","label":"Non fiable"}]'::jsonb, 'c', 'Les entreprises attendent d''être sûres de la reprise avant d''embaucher massivement.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q10', 'analyse-fondamentale', 'macro', 2, 'Une hausse des prix du pétrole bénéficie généralement au :', '[{"id":"a","label":"JPY"},{"id":"b","label":"CAD (Canada)"},{"id":"c","label":"EUR"},{"id":"d","label":"CHF"}]'::jsonb, 'b', 'Le Canada est exportateur net de pétrole ; une hausse améliore sa balance.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q11', 'analyse-fondamentale', 'macro', 2, 'L''« Average Hourly Earnings » aux USA mesure :', '[{"id":"a","label":"Le nombre total d''emplois"},{"id":"b","label":"L''évolution des revenus salariaux"},{"id":"c","label":"Le taux de participation"},{"id":"d","label":"La productivité"}]'::jsonb, 'b', 'Une forte croissance des salaires peut alimenter l''inflation (spirale prix-salaires).', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q12', 'analyse-fondamentale', 'macro', 2, 'Les indices PMI (Purchasing Managers'' Index) sont particulièrement surveillés car :', '[{"id":"a","label":"Ils mesurent l''inflation passée"},{"id":"b","label":"Ils donnent une indication précoce de la santé des secteurs"},{"id":"c","label":"Ils remplacent le PIB"},{"id":"d","label":"Ils sont publiés annuellement"}]'::jsonb, 'b', 'Les PMI sont des indicateurs avancés de l''activité économique.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q13', 'analyse-fondamentale', 'macro', 3, 'Quelle catégorie d''indicateurs regroupe les décisions sur les taux d''intérêt et le forward guidance ?', '[{"id":"a","label":"Indicateurs de croissance"},{"id":"b","label":"Indicateurs d''inflation"},{"id":"c","label":"Indicateurs liés à la politique monétaire"},{"id":"d","label":"Indicateurs de confiance"}]'::jsonb, 'c', 'Ce sont des événements et communications ayant un impact fondamental majeur.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q14', 'analyse-fondamentale', 'macro', 3, 'Une inversion de la courbe des taux (2Y > 10Y) est souvent interprétée comme :', '[{"id":"a","label":"Un signal de croissance forte"},{"id":"b","label":"Un signe avant-coureur de récession"},{"id":"c","label":"Une politique monétaire expansionniste"},{"id":"d","label":"Un indicateur coïncident"}]'::jsonb, 'b', 'L''inversion de la courbe est un indicateur avancé classique de récession.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.2-Q15', 'analyse-fondamentale', 'macro', 3, 'Pourquoi les anticipations de changement de taux sont souvent plus importantes que les changements eux-mêmes ?', '[{"id":"a","label":"Parce que les marchés anticipent et prixent à l''avance"},{"id":"b","label":"Parce que les banques centrales ne changent jamais les taux"},{"id":"c","label":"Parce que les taux sont fixes"},{"id":"d","label":"Parce que les anticipations n''ont aucun impact"}]'::jsonb, 'a', 'Les marchés fonctionnent par anticipation ; le « priced in » est central.', true);

INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q1', 'analyse-fondamentale', 'micro', 1, 'Les données microéconomiques se concentrent principalement sur :', '[{"id":"a","label":"La politique monétaire"},{"id":"b","label":"Les performances individuelles des entreprises"},{"id":"c","label":"Les taux de change"},{"id":"d","label":"Les indicateurs de confiance"}]'::jsonb, 'b', 'La microéconomie analyse les unités économiques individuelles (entreprises, ménages).', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q2', 'analyse-fondamentale', 'micro', 1, 'Le bilan d''une entreprise respecte toujours l''équation :', '[{"id":"a","label":"Actif = Passif − Equity"},{"id":"b","label":"Actif = Passif + Equity"},{"id":"c","label":"Equity = Passif − Actif"},{"id":"d","label":"Passif = Actif + Equity"}]'::jsonb, 'b', 'Actif = Passif + Equity (fondamental de la comptabilité).', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q3', 'analyse-fondamentale', 'micro', 1, 'Le compte de résultat mesure :', '[{"id":"a","label":"La santé financière à un instant T"},{"id":"b","label":"La performance sur une période (revenus, coûts, bénéfices)"},{"id":"c","label":"Les flux de trésorerie"},{"id":"d","label":"La valeur de l''entreprise"}]'::jsonb, 'b', 'Il présente les revenus et charges sur une période donnée.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q4', 'analyse-fondamentale', 'micro', 1, 'Une marge nette de 25 % signifie que :', '[{"id":"a","label":"L''entreprise dégage 25 % de bénéfice net par rapport à ses revenus"},{"id":"b","label":"L''entreprise a 25 % de dette"},{"id":"c","label":"25 % des actifs sont liquides"},{"id":"d","label":"Le ROE est de 25 %"}]'::jsonb, 'a', 'Marge nette = Bénéfice net / Revenus.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q5', 'analyse-fondamentale', 'micro', 1, 'Le ratio dette/équité (D/E) évalue :', '[{"id":"a","label":"La rentabilité"},{"id":"b","label":"Le niveau d''endettement"},{"id":"c","label":"La liquidité"},{"id":"d","label":"La croissance des ventes"}]'::jsonb, 'b', 'Il indique le niveau d''endettement par rapport aux fonds propres.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q6', 'analyse-fondamentale', 'micro', 1, 'Le ROE (Return on Equity) mesure :', '[{"id":"a","label":"La rentabilité des capitaux propres"},{"id":"b","label":"La liquidité de l''entreprise"},{"id":"c","label":"L''endettement total"},{"id":"d","label":"La croissance des revenus"}]'::jsonb, 'a', 'ROE = Bénéfice net / Capitaux propres.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q7', 'analyse-fondamentale', 'micro', 2, 'Un flux de trésorerie libre (Free Cash Flow) élevé indique :', '[{"id":"a","label":"Une forte capacité à générer de la liquidité disponible"},{"id":"b","label":"Une forte dette"},{"id":"c","label":"Une faible rentabilité"},{"id":"d","label":"Un besoin de financement externe"}]'::jsonb, 'a', 'Le FCF représente la liquidité générée après investissements.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q8', 'analyse-fondamentale', 'micro', 2, 'Apple Inc. affichait en 2023 une marge nette de 25 % et un P/E de 28. Cela suggère :', '[{"id":"a","label":"Une valorisation juste proche de la valeur intrinsèque"},{"id":"b","label":"Une entreprise en difficulté"},{"id":"c","label":"Un ratio D/E élevé"},{"id":"d","label":"Une faible croissance"}]'::jsonb, 'a', 'Marge élevée + P/E raisonnable = valorisation alignée avec les fondamentaux.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q9', 'analyse-fondamentale', 'micro', 2, 'Tesla affichait en 2022 un P/E de 50+. Cela reflète principalement :', '[{"id":"a","label":"Une valorisation discount"},{"id":"b","label":"Des attentes de croissance futures très élevées"},{"id":"c","label":"Une faible volatilité"},{"id":"d","label":"Un endettement nul"}]'::jsonb, 'b', 'Un P/E élevé indique que le marché anticipe une forte croissance future.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q10', 'analyse-fondamentale', 'micro', 2, 'Le « Current Ratio » (actifs courants / dettes courantes) mesure :', '[{"id":"a","label":"La rentabilité à long terme"},{"id":"b","label":"La liquidité et la capacité à payer les dettes à court terme"},{"id":"c","label":"L''efficacité opérationnelle"},{"id":"d","label":"La croissance des ventes"}]'::jsonb, 'b', '< 1 = risque de défaut à court terme.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q11', 'analyse-fondamentale', 'micro', 3, 'Pourquoi un ROE élevé via un levier financier (dette) peut être fragile ?', '[{"id":"a","label":"Parce que la dette augmente le risque financier"},{"id":"b","label":"Parce que la dette est toujours mauvaise"},{"id":"c","label":"Parce que le ROE ne compte pas la dette"},{"id":"d","label":"Parce que les actionnaires n''aiment pas la dette"}]'::jsonb, 'a', 'ROE artificiellement gonflé par la dette = risque de faillite accru.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q12', 'analyse-fondamentale', 'micro', 2, 'Dans l''analyse d''un bilan, « Equity » représente :', '[{"id":"a","label":"Les dettes totales"},{"id":"b","label":"La valeur nette appartenant aux actionnaires"},{"id":"c","label":"Les actifs immobilisés"},{"id":"d","label":"Les stocks et créances"}]'::jsonb, 'b', 'Equity = Actif − Passif (fonds propres).', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q13', 'analyse-fondamentale', 'micro', 3, 'Une entreprise avec des revenus en hausse de 51 % (Tesla 2022) mais un P/E de 50 est :', '[{"id":"a","label":"Sous-évaluée"},{"id":"b","label":"Potentiellement surévaluée si la croissance ne se matérialise pas"},{"id":"c","label":"Toujours un bon investissement"},{"id":"d","label":"Sans risque"}]'::jsonb, 'b', 'Le P/E élevé price une croissance future qui peut ne pas se réaliser.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q14', 'analyse-fondamentale', 'micro', 3, 'Le « Quick Ratio » diffère du « Current Ratio » car il exclut :', '[{"id":"a","label":"Les créances clients"},{"id":"b","label":"Les stocks (inventaire)"},{"id":"c","label":"Les liquidités"},{"id":"d","label":"Les dettes à long terme"}]'::jsonb, 'b', 'Quick Ratio = (Actifs courants − Stocks) / Dettes courantes (plus conservateur).', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.3-Q15', 'analyse-fondamentale', 'micro', 3, 'Pourquoi les marges brutes et nettes doivent être analysées ensemble ?', '[{"id":"a","label":"Parce qu''elles mesurent la même chose"},{"id":"b","label":"Parce que l''écart entre les deux révèle l''efficacité opérationnelle et les coûts indirects"},{"id":"c","label":"Parce que la marge brute suffit"},{"id":"d","label":"Parce que la marge nette n''a pas d''importance"}]'::jsonb, 'b', 'Marge brute − coûts opérationnels = marge nette. Un écart anormal signale un problème.', true);

INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q1', 'analyse-fondamentale', 'outils', 1, 'Le ratio P/E (Price-to-Earnings) mesure :', '[{"id":"a","label":"La valorisation par rapport aux bénéfices"},{"id":"b","label":"La rentabilité des capitaux propres"},{"id":"c","label":"Le niveau d''endettement"},{"id":"d","label":"La liquidité"}]'::jsonb, 'a', 'P/E = Cours / BPA. Indique combien d''années de bénéfices sont payées.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q2', 'analyse-fondamentale', 'outils', 1, 'Le modèle DCF (Discounted Cash Flow) estime la valeur intrinsèque via :', '[{"id":"a","label":"Les flux de trésorerie futurs actualisés"},{"id":"b","label":"Le cours de bourse moyen"},{"id":"c","label":"Les volumes de transactions"},{"id":"d","label":"Le sentiment des analystes"}]'::jsonb, 'a', 'DCF = somme des FCF futurs actualisés + valeur terminale.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q3', 'analyse-fondamentale', 'outils', 1, 'L''analyse sectorielle vise à :', '[{"id":"a","label":"Identifier les tendances et défis spécifiques à un secteur"},{"id":"b","label":"Prédire le cours du pétrole"},{"id":"c","label":"Mesurer l''inflation"},{"id":"d","label":"Calculer le PIB"}]'::jsonb, 'a', 'Elle compare les performances au sein d''un secteur pour identifier leaders et laggards.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q4', 'analyse-fondamentale', 'outils', 1, 'L''analyse SWOT examine :', '[{"id":"a","label":"Les forces, faiblesses, opportunités et menaces"},{"id":"b","label":"Les salaires et les coûts"},{"id":"c","label":"Les taux d''intérêt et l''inflation"},{"id":"d","label":"Les volumes et la volatilité"}]'::jsonb, 'a', 'SWOT = outil stratégique d''évaluation qualitative.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q5', 'analyse-fondamentale', 'outils', 1, 'Un ratio D/E < 1 est généralement interprété comme :', '[{"id":"a","label":"Un endettement excessif"},{"id":"b","label":"Une santé financière raisonnable"},{"id":"c","label":"Une rentabilité faible"},{"id":"d","label":"Une liquidité insuffisante"}]'::jsonb, 'b', 'Moins de dette que de fonds propres = structure financière conservative.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q6', 'analyse-fondamentale', 'outils', 2, 'Le P/B (Price-to-Book) compare :', '[{"id":"a","label":"Le cours de bourse à la valeur comptable par action"},{"id":"b","label":"Le bénéfice net aux dividendes"},{"id":"c","label":"La dette aux revenus"},{"id":"d","label":"Le cours au flux de trésorerie"}]'::jsonb, 'a', 'Utile pour évaluer les entreprises à fort actif tangible (banques, industrie).', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q7', 'analyse-fondamentale', 'outils', 2, 'Dans un modèle DCF, le WACC représente :', '[{"id":"a","label":"Le taux de croissance des revenus"},{"id":"b","label":"Le coût moyen pondéré du capital"},{"id":"c","label":"Le bénéfice par action"},{"id":"d","label":"Le taux d''actualisation du risque pays"}]'::jsonb, 'b', 'WACC = coût moyen pondéré du capital, paramètre le plus sensible du DCF.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q8', 'analyse-fondamentale', 'outils', 2, 'Pourquoi le P/E d''Apple (28 en 2023) peut être considéré comme supérieur à la moyenne du secteur ?', '[{"id":"a","label":"Parce qu''Apple est en faillite"},{"id":"b","label":"Parce que la prime reflète la qualité, l''écosystème et la croissance des services"},{"id":"c","label":"Parce que le secteur tech a un P/E moyen de 50"},{"id":"d","label":"Parce que le P/E n''a pas d''importance"}]'::jsonb, 'b', 'Une prime est justifiée par des avantages concurrentiels durables.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q9', 'analyse-fondamentale', 'outils', 2, 'La comparaison Tesla vs Ford (P/E 50 vs 10) reflète :', '[{"id":"a","label":"Que Ford est toujours meilleur"},{"id":"b","label":"Des perspectives de croissance et de risque différentes"},{"id":"c","label":"Que Tesla est sous-évaluée"},{"id":"d","label":"Que le P/E est inutile"}]'::jsonb, 'b', 'Un P/E élevé = croissance attendue ; un P/E bas = maturité ou difficultés.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q10', 'analyse-fondamentale', 'outils', 2, 'L''analyse comparative (peer comparison) permet de :', '[{"id":"a","label":"Identifier les écarts de valorisation justifiés ou non"},{"id":"b","label":"Prédire les taux de change"},{"id":"c","label":"Mesurer l''inflation"},{"id":"d","label":"Calculer le PIB"}]'::jsonb, 'a', 'Comparer avec des pairs aide à détecter surévaluation ou sous-évaluation.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q11', 'analyse-fondamentale', 'outils', 3, 'Pourquoi le modèle DCF est-il particulièrement sensible au WACC ?', '[{"id":"a","label":"Parce que +1 % WACC = −15 à −20 % valorisation"},{"id":"b","label":"Parce que le WACC n''a pas d''impact"},{"id":"c","label":"Parce que le WACC est fixe"},{"id":"d","label":"Parce que le WACC remplace la croissance"}]'::jsonb, 'a', 'Le WACC est le paramètre le plus critique du DCF.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q12', 'analyse-fondamentale', 'outils', 2, 'Dans l''analyse SWOT de Netflix, « Base d''abonnés mondiale » est une :', '[{"id":"a","label":"Faiblesse"},{"id":"b","label":"Force"},{"id":"c","label":"Menace"},{"id":"d","label":"Opportunité"}]'::jsonb, 'b', 'C''est un avantage concurrentiel structurel.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q13', 'analyse-fondamentale', 'outils', 3, 'Pourquoi un multiple absolu (ex: P/E 30) peut être trompeur ?', '[{"id":"a","label":"Parce qu''il dépend du secteur et du cycle économique"},{"id":"b","label":"Parce que 30 est toujours cher"},{"id":"c","label":"Parce que les multiples ne servent à rien"},{"id":"d","label":"Parce que le P/E est illégal"}]'::jsonb, 'a', 'P/E 30 = cher (utility) vs normal (tech croissance). Le contexte sectoriel est essentiel.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q14', 'analyse-fondamentale', 'outils', 3, 'La « valeur terminale » dans un DCF représente généralement :', '[{"id":"a","label":"10-20 % de la valorisation totale"},{"id":"b","label":"60-80 % de la valorisation totale"},{"id":"c","label":"0 % de la valorisation"},{"id":"d","label":"La dette nette"}]'::jsonb, 'b', 'La majeure partie de la valeur vient des flux lointains, d''où la sensibilité aux hypothèses.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q15', 'analyse-fondamentale', 'outils', 3, 'Pourquoi l''analyse fondamentale d''une banque diffère-t-elle de celle d''une entreprise tech ?', '[{"id":"a","label":"Parce que les banques n''ont pas de bilan"},{"id":"b","label":"Parce que les métriques clés sont différentes (NIM, CET1, provisions vs ARR, churn)"},{"id":"c","label":"Parce que les banques ne sont pas cotées"},{"id":"d","label":"Parce que l''AF ne s''applique pas aux banques"}]'::jsonb, 'b', 'Chaque secteur a ses propres ratios et drivers de valeur.', true);

INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q1', 'analyse-fondamentale', 'previsions', 1, 'Les prévisions financières combinent :', '[{"id":"a","label":"Données historiques, tendances sectorielles et projections économiques"},{"id":"b","label":"Seulement des données historiques"},{"id":"c","label":"Seulement des opinions d''analystes"},{"id":"d","label":"Des graphiques techniques uniquement"}]'::jsonb, 'a', 'La prévision est un processus multi-inputs.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q2', 'analyse-fondamentale', 'previsions', 1, 'L''analyse des tendances historiques vise à :', '[{"id":"a","label":"Identifier des patterns dans les revenus et bénéfices"},{"id":"b","label":"Prédire la météo"},{"id":"c","label":"Calculer le PIB"},{"id":"d","label":"Mesurer l''inflation"}]'::jsonb, 'a', 'Elle repose sur la continuité des performances passées.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q3', 'analyse-fondamentale', 'previsions', 1, 'Une guidance « raised » (revue à la hausse) par une entreprise est généralement interprétée comme :', '[{"id":"a","label":"Un signal négatif"},{"id":"b","label":"Un signal positif sur les perspectives"},{"id":"c","label":"Sans impact"},{"id":"d","label":"Une manipulation de marché"}]'::jsonb, 'b', 'La direction confirme une performance meilleure que prévu.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q4', 'analyse-fondamentale', 'previsions', 1, 'Dans la modélisation par scénarios, on prépare généralement :', '[{"id":"a","label":"Un seul scénario optimiste"},{"id":"b","label":"Trois scénarios (optimiste, neutre, pessimiste)"},{"id":"c","label":"Un scénario unique sans risque"},{"id":"d","label":"Aucun scénario"}]'::jsonb, 'b', 'La préparation multi-scénarios permet d''évaluer l''asymétrie risque/rendement.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q5', 'analyse-fondamentale', 'previsions', 2, 'La « valeur espérée » dans un planificateur de scénarios est calculée comme :', '[{"id":"a","label":"La moyenne simple des trois scénarios"},{"id":"b","label":"Σ(probabilité × valorisation scénario)"},{"id":"c","label":"Le scénario le plus probable uniquement"},{"id":"d","label":"La médiane des scénarios"}]'::jsonb, 'b', 'C''est la somme pondérée des valeurs par leurs probabilités.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q6', 'analyse-fondamentale', 'previsions', 2, 'Pourquoi la guidance est-elle souvent plus importante que le beat/miss actuel ?', '[{"id":"a","label":"Parce qu''elle oriente les attentes futures du marché"},{"id":"b","label":"Parce que le passé n''a pas d''importance"},{"id":"c","label":"Parce que les résultats actuels sont faux"},{"id":"d","label":"Parce que la guidance est obligatoire"}]'::jsonb, 'a', 'Le marché anticipe ; une guidance lowered peut faire chuter le cours malgré un beat.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q7', 'analyse-fondamentale', 'previsions', 2, 'Un scénario de prévision « sans risque » est :', '[{"id":"a","label":"Idéal pour la prise de décision"},{"id":"b","label":"Un biais cognitif dangereux"},{"id":"c","label":"Recommandé par les banques centrales"},{"id":"d","label":"Toujours exact"}]'::jsonb, 'b', 'Ne pas préparer de scénario adverse = absence de plan de sortie.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q8', 'analyse-fondamentale', 'previsions', 2, 'Si la valeur espérée d''une action est supérieure au cours actuel, cela suggère :', '[{"id":"a","label":"Une asymétrie positive (upside)"},{"id":"b","label":"Une asymétrie négative (downside)"},{"id":"c","label":"Que le marché a toujours raison"},{"id":"d","label":"Qu''il faut vendre immédiatement"}]'::jsonb, 'a', 'Cela indique un potentiel de sous-évaluation selon les hypothèses du modèle.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q9', 'analyse-fondamentale', 'previsions', 2, 'Un beat d''EPS de 1-2 % par rapport au consensus est généralement considéré comme :', '[{"id":"a","label":"Un fort signal"},{"id":"b","label":"Un bruit de marché faible"},{"id":"c","label":"Une catastrophe"},{"id":"d","label":"Un dividende"}]'::jsonb, 'b', 'Un écart faible peut être dû à des facteurs comptables non récurrents.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q10', 'analyse-fondamentale', 'previsions', 2, 'Pourquoi faut-il toujours définir une invalidation avant une entrée en position ?', '[{"id":"a","label":"Parce que c''est une règle de l''AMF"},{"id":"b","label":"Parce qu''un scénario sans sortie = biais de confirmation"},{"id":"c","label":"Parce que les stops sont interdits"},{"id":"d","label":"Parce que l''invalidation est optionnelle"}]'::jsonb, 'b', 'Définir la sortie avant l''entrée évite le biais de rationalisation post-hoc.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q11', 'analyse-fondamentale', 'previsions', 2, 'La prévision du prix de l''or à 2000 $/once « en cas de tensions géopolitiques » est un exemple de :', '[{"id":"a","label":"Analyse technique"},{"id":"b","label":"Scénario conditionnel macroéconomique"},{"id":"c","label":"Manipulation de marché"},{"id":"d","label":"Donnée historique"}]'::jsonb, 'b', 'C''est une prévision dépendante d''un catalyseur externe.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q12', 'analyse-fondamentale', 'previsions', 3, 'Pourquoi les prévisions de taux d''intérêt par la Fed impactent-elles les obligations ?', '[{"id":"a","label":"Parce que les obligations sont sensibles aux taux (duration)"},{"id":"b","label":"Parce que la Fed achète des obligations"},{"id":"c","label":"Parce que les obligations ne rapportent rien"},{"id":"d","label":"Parce que les taux sont fixes"}]'::jsonb, 'a', 'La duration mesure la sensibilité du prix d''une obligation aux variations de taux.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q13', 'analyse-fondamentale', 'previsions', 3, 'Un scénario pessimiste pour l''industrie automobile (-10 % en cas de récession) illustre :', '[{"id":"a","label":"L''importance du stress testing"},{"id":"b","label":"Que l''automobile est sans risque"},{"id":"c","label":"Que la récession n''existe pas"},{"id":"d","label":"Que les scénarios sont inutiles"}]'::jsonb, 'a', 'Le stress testing évalue la résilience face aux chocs macro.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q14', 'analyse-fondamentale', 'previsions', 2, 'La probabilité totale des trois scénarios (optimiste, neutre, pessimiste) doit être :', '[{"id":"a","label":"Supérieure à 100 %"},{"id":"b","label":"Égale à 100 %"},{"id":"c","label":"Inférieure à 50 %"},{"id":"d","label":"Variable selon le marché"}]'::jsonb, 'b', 'C''est une distribution de probabilités complète.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.5-Q15', 'analyse-fondamentale', 'previsions', 3, 'Pourquoi les prévisions à long terme (5-10 ans) sont-elles intrinsèquement moins fiables ?', '[{"id":"a","label":"Parce que l''incertitude cumulée des hypothèses croît exponentiellement"},{"id":"b","label":"Parce que les analystes sont incompétents"},{"id":"c","label":"Parce que les données historiques n''existent pas"},{"id":"d","label":"Parce que les marchés sont parfaits"}]'::jsonb, 'a', 'Les petites variations d''hypothèses se compoundent sur la durée.', true);

INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ1', 'analyse-fondamentale', 'intro', 1, 'Dans le MarketDriverVisualizer, la chaîne causale s''affiche comme :', '[{"id":"a","label":"Un tableau de chiffres"},{"id":"b","label":"Driver → Canal → Actif impacté → Invalidation"},{"id":"c","label":"Un graphique en camembert"},{"id":"d","label":"Une liste alphabétique"}]'::jsonb, 'b', 'La logique est la transmission causale avec condition de sortie explicite.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ2', 'analyse-fondamentale', 'intro', 1, 'Le MacroRegimeRadar affiche 4 régimes principaux. Lequel correspond à « croissance forte + inflation modérée » ?', '[{"id":"a","label":"Stagflation"},{"id":"b","label":"Récession"},{"id":"c","label":"Goldilocks"},{"id":"d","label":"Déflation"}]'::jsonb, 'c', 'Goldilocks = croissance saine + inflation contrôlée.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ3', 'analyse-fondamentale', 'intro', 2, 'Dans le MarketDriverVisualizer, l''« invalidation » représente :', '[{"id":"a","label":"Une erreur de calcul"},{"id":"b","label":"La condition de sortie qui rend la thèse caduque"},{"id":"c","label":"Un achat forcé"},{"id":"d","label":"Une news positive"}]'::jsonb, 'b', 'C''est le mécanisme de gestion du risque : quand la thèse est invalidée, on sort.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ4', 'analyse-fondamentale', 'intro', 2, 'Sur le MacroRegimeRadar, l''axe « Liquidité » mesure principalement :', '[{"id":"a","label":"Le volume des transactions"},{"id":"b","label":"La politique monétaire (QE/QT, taux)"},{"id":"c","label":"Le nombre d''employés"},{"id":"d","label":"Le PIB"}]'::jsonb, 'b', 'Liquidité = politique monétaire, spreads de crédit, conditions financières.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ5', 'analyse-fondamentale', 'intro', 2, 'Le régime « Stagflation » sur le radar implique généralement :', '[{"id":"a","label":"Actions haussières + obligations haussières"},{"id":"b","label":"Croissance faible + inflation élevée"},{"id":"c","label":"Croissance forte + inflation nulle"},{"id":"d","label":"Déflation + chômage faible"}]'::jsonb, 'b', 'Stagflation = stagnation économique + inflation persistante.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ6', 'analyse-fondamentale', 'intro', 2, 'Dans le MarketDriverVisualizer, si le driver sélectionné est « NFP fort », le canal de transmission vers l''USD est :', '[{"id":"a","label":"Politique fiscale"},{"id":"b","label":"Politique monétaire (taux réels, anticipations Fed)"},{"id":"c","label":"Balance commerciale"},{"id":"d","label":"Rien, le NFP n''impacte pas l''USD"}]'::jsonb, 'b', 'NFP fort → Fed hawkish → taux ↑ → USD ↑.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ7', 'analyse-fondamentale', 'intro', 2, 'Le MacroRegimeRadar utilise un polygone à 6 axes. Lequel de ces axes n''est PAS affiché ?', '[{"id":"a","label":"PIB"},{"id":"b","label":"Inflation"},{"id":"c","label":"Taux directeurs"},{"id":"d","label":"Dividendes"}]'::jsonb, 'd', 'Les 6 axes sont : PIB, IPC, Taux, Liquidité, Sentiment, Crédit.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ8', 'analyse-fondamentale', 'intro', 3, 'Si le radar indique un score élevé sur « Inflation » et « Taux », mais faible sur « PIB », le régime probable est :', '[{"id":"a","label":"Expansion"},{"id":"b","label":"Stagflation"},{"id":"c","label":"Goldilocks"},{"id":"d","label":"Récession pure"}]'::jsonb, 'b', 'Inflation haute + croissance faible = Stagflation.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ9', 'analyse-fondamentale', 'intro', 3, 'Dans le MarketDriverVisualizer, l''invalidation d''un driver « PIB fort » pourrait être :', '[{"id":"a","label":"Une révision à la baisse du PIB"},{"id":"b","label":"Une hausse des salaires"},{"id":"c","label":"Une baisse du chômage"},{"id":"d","label":"Un excédent commercial"}]'::jsonb, 'a', 'Si le PIB est révisé à la baisse, la thèse de croissance forte s''effondre.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ10', 'analyse-fondamentale', 'intro', 3, 'Pourquoi le MacroRegimeRadar est-il plus utile qu''un indicateur macro isolé ?', '[{"id":"a","label":"Parce qu''il est plus coloré"},{"id":"b","label":"Parce qu''il force la lecture multi-dimensionnelle (croisement de plusieurs facteurs)"},{"id":"c","label":"Parce qu''il prédit le cours exact"},{"id":"d","label":"Parce qu''il remplace l''analyse technique"}]'::jsonb, 'b', 'La macro est multi-factorielle ; le radar évite le diagnostic mono-variable.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ1', 'analyse-fondamentale', 'macro', 1, 'Le MacroDashboard affiche 11 indicateurs sous forme de :', '[{"id":"a","label":"Graphique linéaire unique"},{"id":"b","label":"Tuiles synthèse (Réel / Consensus / Précédent)"},{"id":"c","label":"Tableau Excel"},{"id":"d","label":"Carte géographique"}]'::jsonb, 'b', 'C''est un command center avec filtres par catégorie et modal détail.', 'MacroDashboard', 'a5', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ2', 'analyse-fondamentale', 'macro', 1, 'Dans l''EconomicCycleWheel, la phase « Récession » favorise généralement :', '[{"id":"a","label":"Les actions cycliques"},{"id":"b","label":"L''or et les obligations souveraines"},{"id":"c","label":"Les devises des marchés émergents"},{"id":"d","label":"Les matières premières industrielles"}]'::jsonb, 'b', 'Récession = fuite vers la qualité (safe havens).', 'EconomicCycleWheel', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ3', 'analyse-fondamentale', 'macro', 1, 'Le FedSimulator utilise deux sliders principaux :', '[{"id":"a","label":"PIB et balance commerciale"},{"id":"b","label":"CPI et NFP"},{"id":"c","label":"Or et pétrole"},{"id":"d","label":"Actions et obligations"}]'::jsonb, 'b', 'La matrice décision Fed croise inflation et emploi.', 'FedSimulator', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ4', 'analyse-fondamentale', 'macro', 2, 'Dans le NfpInterpreter, une surprise de +2σ (sigma) est interprétée comme :', '[{"id":"a","label":"Un bruit statistique"},{"id":"b","label":"Un signal fort susceptible de déclencher une réaction Fed"},{"id":"c","label":"Sans impact sur les marchés"},{"id":"d","label":"Un indicateur retardé"}]'::jsonb, 'b', '>2σ = magnitude exceptionnelle = réaction institutionnelle probable.', 'NfpInterpreter', 'a4', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ5', 'analyse-fondamentale', 'macro', 2, 'Le YieldCurveVisualizer affiche une courbe « inversée » quand :', '[{"id":"a","label":"Les taux longs sont supérieurs aux taux courts"},{"id":"b","label":"Les taux courts sont supérieurs aux taux longs (ex: 2Y > 10Y)"},{"id":"c","label":"Tous les taux sont nuls"},{"id":"d","label":"La Fed baisse les taux"}]'::jsonb, 'b', 'Inversion 2Y/10Y = signal récession classique.', 'YieldCurveVisualizer', 'a14', true);

INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ6', 'analyse-fondamentale', 'macro', 2, 'Dans le GdpCpiInterpreters, la combinaison PIB fort + CPI bas correspond au régime :', '[{"id":"a","label":"Stagflation"},{"id":"b","label":"Goldilocks"},{"id":"c","label":"Récession"},{"id":"d","label":"Hyperinflation"}]'::jsonb, 'b', 'Croissance saine + inflation maîtrisée = environnement idéal.', 'GdpCpiInterpreters', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ7', 'analyse-fondamentale', 'macro', 2, 'L''IntermarketCorrelationMap affiche une corrélation négative (rouge) entre DXY et EUR/USD. Cela signifie :', '[{"id":"a","label":"Quand le dollar monte, l''euro tend à baisser"},{"id":"b","label":"Les deux montent ensemble"},{"id":"c","label":"Aucun lien entre les deux"},{"id":"d","label":"La corrélation est décorative"}]'::jsonb, 'a', 'Corrélation négative = mouvements inverses.', 'IntermarketCorrelationMap', 'a13', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ8', 'analyse-fondamentale', 'macro', 2, 'Dans le MacroIndicatorLab, la « surprise » est calculée comme :', '[{"id":"a","label":"Consensus − Réel"},{"id":"b","label":"Réel − Consensus"},{"id":"c","label":"Réel + Consensus"},{"id":"d","label":"Réel / Consensus"}]'::jsonb, 'b', 'Surprise = Réel − Consensus (beat si > 0, miss si < 0).', 'MacroIndicatorLab', 'a2', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ9', 'analyse-fondamentale', 'macro', 2, 'Le MacroRelationshipEngine affiche une chaîne : CPI ↑ → Fed hawkish → USD ↑. Le mécanisme de transmission est :', '[{"id":"a","label":"La politique monétaire restrictive renforce la devise"},{"id":"b","label":"L''inflation affaiblit toujours la devise"},{"id":"c","label":"La Fed achète des devises"},{"id":"d","label":"Le USD monte sans raison"}]'::jsonb, 'a', 'Hawkish = taux ↑ → attrait des capitaux → devise ↑.', 'MacroRelationshipEngine', 'a2', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ10', 'analyse-fondamentale', 'macro', 2, 'Sur le YieldCurveVisualizer, une courbe « plate » suggère :', '[{"id":"a","label":"Une croissance explosive imminente"},{"id":"b","label":"Une transition ou incertitude économique"},{"id":"c","label":"Une inflation galopante"},{"id":"d","label":"Un défaut souverain"}]'::jsonb, 'b', 'Courbe plate = marché incertain sur la direction future.', 'YieldCurveVisualizer', 'a14', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ11', 'analyse-fondamentale', 'macro', 2, 'Dans le MacroDashboard, un indicateur affichant « Beat » avec un consensus dépassé signifie :', '[{"id":"a","label":"Le réel est inférieur au consensus"},{"id":"b","label":"Le réel est supérieur au consensus"},{"id":"c","label":"Le réel égale le consensus"},{"id":"d","label":"L''indicateur est annulé"}]'::jsonb, 'b', 'Beat = réel > consensus (surprise positive).', 'MacroDashboard', 'a5', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ12', 'analyse-fondamentale', 'macro', 3, 'L''EconomicCycleWheel permet de distinguer :', '[{"id":"a","label":"Le cycle économique (phases macro) de la tendance prix (direction)"},{"id":"b","label":"Le cycle des lave-vaisselle"},{"id":"c","label":"Le PIB et l''inflation uniquement"},{"id":"d","label":"Les taux et les devises"}]'::jsonb, 'a', 'Cycle ≠ tendance. La roue montre les phases macro, pas les graphiques de prix.', 'EconomicCycleWheel', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ13', 'analyse-fondamentale', 'macro', 3, 'Dans le FedSimulator, la combinaison CPI 5 % + NFP 300K produit probablement une décision :', '[{"id":"a","label":"Dovish (baisse des taux)"},{"id":"b","label":"Hawkish (maintien ou hausse des taux)"},{"id":"c","label":"Neutre sans changement"},{"id":"d","label":"QE illimité"}]'::jsonb, 'b', 'Inflation chaude + emploi fort = Fed restrictive.', 'FedSimulator', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ14', 'analyse-fondamentale', 'macro', 3, 'Sur l''IntermarketCorrelationMap, une cassure de corrélation historique (gris) entre l''or et le DXY peut signaler :', '[{"id":"a","label":"Un retour à la normale"},{"id":"b","label":"Un choc systémique ou un changement de régime macro"},{"id":"c","label":"Une erreur de données"},{"id":"d","label":"Rien de particulier"}]'::jsonb, 'b', 'Décorrélation soudaine = crise ou changement de paradigme.', 'IntermarketCorrelationMap', 'a13', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ15', 'analyse-fondamentale', 'macro', 3, 'Le NfpInterpreter croise le NFP avec les salaires horaires moyens car :', '[{"id":"a","label":"Les salaires sont décoratifs"},{"id":"b","label":"La pression salariale alimente l''inflation (spirale prix-salaires)"},{"id":"c","label":"Les salaires n''ont aucun lien avec la Fed"},{"id":"d","label":"Le NFP seul suffit"}]'::jsonb, 'b', 'NFP + salaires = lecture complète du marché du travail pour la Fed.', 'NfpInterpreter', 'a4', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ1', 'analyse-fondamentale', 'micro', 1, 'Le CompanyHealthScore agrège 4 dimensions. Laquelle n''est PAS incluse ?', '[{"id":"a","label":"Croissance"},{"id":"b","label":"Marges"},{"id":"c","label":"Dette"},{"id":"d","label":"Dividende"}]'::jsonb, 'd', 'Les 4 dimensions sont : Croissance, Marges, Dette, Liquidité.', 'CompanyHealthScore', 'a6', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ2', 'analyse-fondamentale', 'micro', 1, 'Dans le BalanceSheetExplorer, l''équation fondamentale est :', '[{"id":"a","label":"Actif = Passif + Equity"},{"id":"b","label":"Revenus = Bénéfices + Dividendes"},{"id":"c","label":"Dette = Actif − Cash"},{"id":"d","label":"Equity = Dette × ROE"}]'::jsonb, 'a', 'C''est la base de la comptabilité en partie double.', 'BalanceSheetExplorer', 'a8', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ3', 'analyse-fondamentale', 'micro', 1, 'Le CompanyDashboard affiche les KPI sous forme de :', '[{"id":"a","label":"Graphique en camembert"},{"id":"b","label":"Tuiles synthèse avec lecture croisée"},{"id":"c","label":"Tableau Excel brut"},{"id":"d","label":"Carte géographique"}]'::jsonb, 'b', 'C''est une vue synthèse rapide pour le diagnostic micro.', 'CompanyDashboard', 'a3', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ4', 'analyse-fondamentale', 'micro', 2, 'Un score CompanyHealthScore > 75 est interprété comme :', '[{"id":"a","label":"Un red flag immédiat"},{"id":"b","label":"Une qualité institutionnelle"},{"id":"c","label":"Une valorisation excessive"},{"id":"d","label":"Un risque de faillite"}]'::jsonb, 'b', '> 75 = entreprise solide sur les 4 dimensions.', 'CompanyHealthScore', 'a6', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ5', 'analyse-fondamentale', 'micro', 2, 'Dans le FinancialRatios, un ROE > 15 % est généralement considéré comme :', '[{"id":"a","label":"Faible"},{"id":"b","label":"De qualité institutionnelle"},{"id":"c","label":"Négatif"},{"id":"d","label":"Sans importance"}]'::jsonb, 'b', 'Seuil classique de rentabilité des fonds propres.', 'FinancialRatios', 'a7', true);

INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ6', 'analyse-fondamentale', 'micro', 2, 'Le Current Ratio dans le FinancialRatios mesure :', '[{"id":"a","label":"La rentabilité"},{"id":"b","label":"La liquidité à court terme (actifs courants / dettes courantes)"},{"id":"c","label":"L''endettement total"},{"id":"d","label":"La croissance"}]'::jsonb, 'b', '< 1 = risque de défaut à court terme.', 'FinancialRatios', 'a7', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ7', 'analyse-fondamentale', 'micro', 2, 'Dans le BalanceSheetExplorer, si Actif < Passif, l''entreprise est :', '[{"id":"a","label":"Très rentable"},{"id":"b","label":"Techniquement insolvable"},{"id":"c","label":"En croissance"},{"id":"d","label":"Sous-évaluée"}]'::jsonb, 'b', 'L''équilibre comptable est rompu = insolvabilité technique.', 'BalanceSheetExplorer', 'a8', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ8', 'analyse-fondamentale', 'micro', 2, 'Le CompanyDashboard suggère qu''un seul KPI « ne raconte rien ». Pourquoi ?', '[{"id":"a","label":"Parce que les KPI sont faux"},{"id":"b","label":"Parce qu''il faut croiser Croissance + Marges + Dette + Cash"},{"id":"c","label":"Parce que le dashboard est inutile"},{"id":"d","label":"Parce que les marchés sont efficients"}]'::jsonb, 'b', 'La microéconomie exige la lecture croisée (ex: profitable + surendetté = fragile).', 'CompanyDashboard', 'a3', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ9', 'analyse-fondamentale', 'micro', 2, 'Un D/E < 1 dans le FinancialRatios indique :', '[{"id":"a","label":"Plus de fonds propres que de dette"},{"id":"b","label":"Plus de dette que de fonds propres"},{"id":"c","label":"Une absence totale de dette"},{"id":"d","label":"Une faillite imminente"}]'::jsonb, 'a', 'Structure financière conservative.', 'FinancialRatios', 'a7', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ10', 'analyse-fondamentale', 'micro', 3, 'Pourquoi le ROE élevé via levier (dette) est-il signalé comme « fragile » dans le FinancialRatios ?', '[{"id":"a","label":"Parce que la dette augmente le risque financier en cas de choc"},{"id":"b","label":"Parce que la dette est interdite"},{"id":"c","label":"Parce que le ROE est faux"},{"id":"d","label":"Parce que les actionnaires préfèrent le cash"}]'::jsonb, 'a', 'ROE artificiellement gonflé = risque de faillite si les taux montent.', 'FinancialRatios', 'a7', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ11', 'analyse-fondamentale', 'micro', 3, 'Dans le BalanceSheetExplorer, le « Current Ratio » < 1 signifie concrètement :', '[{"id":"a","label":"L''entreprise ne peut pas couvrir ses dettes à court terme avec ses actifs liquides"},{"id":"b","label":"L''entreprise est très rentable"},{"id":"c","label":"L''entreprise a trop de cash"},{"id":"d","label":"Rien de particulier"}]'::jsonb, 'a', 'C''est un signal d''alerte de liquidité.', 'BalanceSheetExplorer', 'a8', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ12', 'analyse-fondamentale', 'micro', 3, 'Pourquoi le CompanyHealthScore pondère-t-il la « Croissance » à 30 % et la « Liquidité » à 20 % ?', '[{"id":"a","label":"Parce que la croissance est le meilleur prédicteur de création de valeur à long terme"},{"id":"b","label":"Parce que la liquidité n''a pas d''importance"},{"id":"c","label":"Parce que les pondérations sont aléatoires"},{"id":"d","label":"Parce que la dette est plus importante"}]'::jsonb, 'a', 'La croissance est le moteur principal, mais la liquidité reste critique (20 %).', 'CompanyHealthScore', 'a6', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ1', 'analyse-fondamentale', 'outils', 1, 'Le ValuationLab permet de tester :', '[{"id":"a","label":"Les ratios de liquidité"},{"id":"b","label":"Les multiples P/E, P/S, P/B et leur prime/décote sectorielle"},{"id":"c","label":"Les taux de change"},{"id":"d","label":"L''inflation"}]'::jsonb, 'b', 'C''est un laboratoire de valorisation par multiples.', 'ValuationLab', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ2', 'analyse-fondamentale', 'outils', 1, 'Dans le DcfSimulator, le paramètre le plus sensible est :', '[{"id":"a","label":"La croissance des revenus"},{"id":"b","label":"Le WACC"},{"id":"c","label":"La marge nette"},{"id":"d","label":"Le nombre d''employés"}]'::jsonb, 'b', '+1 % WACC = −15 à −20 % valorisation.', 'DcfSimulator', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ3', 'analyse-fondamentale', 'outils', 1, 'Le PeerComparisonMatrix compare une entreprise à :', '[{"id":"a","label":"Des concurrents du même secteur"},{"id":"b","label":"Des entreprises aléatoires"},{"id":"c","label":"Des indices boursiers"},{"id":"d","label":"Des banques centrales"}]'::jsonb, 'a', 'C''est la comparaison avec des pairs (peers).', 'PeerComparisonMatrix', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ4', 'analyse-fondamentale', 'outils', 2, 'Dans l''EarningsImpactEngine, un « Beat + Guidance Lowered » est généralement interprété comme :', '[{"id":"a","label":"Très positif"},{"id":"b","label":"Souvent négatif (le marché privilégie les perspectives)"},{"id":"c","label":"Neutre"},{"id":"d","label":"Sans impact"}]'::jsonb, 'b', 'La guidance > beat actuel. Lowered = dégradation attendue.', 'EarningsImpactEngine', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ5', 'analyse-fondamentale', 'outils', 2, 'Le DcfSimulator affiche la « valeur terminale » comme représentant :', '[{"id":"a","label":"5 % de la valorisation"},{"id":"b","label":"60-80 % de la valorisation totale"},{"id":"c","label":"La dette nette"},{"id":"d","label":"Les dividendes"}]'::jsonb, 'b', 'La majorité de la valeur vient des flux lointains.', 'DcfSimulator', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ6', 'analyse-fondamentale', 'outils', 2, 'Dans le ValuationLab, un multiple supérieur à la médiane sectorielle signifie :', '[{"id":"a","label":"Une décote automatique"},{"id":"b","label":"Une prime (croissance ou qualité supérieure)"},{"id":"c","label":"Une erreur de calcul"},{"id":"d","label":"Un red flag"}]'::jsonb, 'b', 'Prime justifiée par des fondamentaux supérieurs.', 'ValuationLab', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ7', 'analyse-fondamentale', 'outils', 2, 'Le PeerComparisonMatrix identifie un « laggard » comme :', '[{"id":"a","label":"Une entreprise avec ROE élevé et marges supérieures"},{"id":"b","label":"Une entreprise avec multiples bas et marges compressées"},{"id":"c","label":"Une entreprise en forte croissance"},{"id":"d","label":"Une entreprise sans dette"}]'::jsonb, 'b', 'Laggard = sous-performeur structurel du secteur.', 'PeerComparisonMatrix', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ8', 'analyse-fondamentale', 'outils', 2, 'Dans l''EarningsImpactEngine, une surprise EPS > 5 % est considérée comme :', '[{"id":"a","label":"Un bruit de marché"},{"id":"b","label":"Un fort signal"},{"id":"c","label":"Sans importance"},{"id":"d","label":"Un dividende exceptionnel"}]'::jsonb, 'b', '> 5 % = magnitude significative = réaction cours probable.', 'EarningsImpactEngine', 'a12', true);

INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ9', 'analyse-fondamentale', 'outils', 3, 'Pourquoi le ValuationLab suggère-t-il de tester la sensibilité EPS ± 10 % ?', '[{"id":"a","label":"Parce que les résultats sont toujours faux"},{"id":"b","label":"Pour évaluer la robustesse de la valorisation face à l''incertitude"},{"id":"c","label":"Parce que c''est obligatoire"},{"id":"d","label":"Pour augmenter le P/E"}]'::jsonb, 'b', 'Le stress testing des hypothèses est central en institutionnel.', 'ValuationLab', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ10', 'analyse-fondamentale', 'outils', 3, 'Dans le DcfSimulator, un taux de croissance perpétuel de 6 % est :', '[{"id":"a","label":"Conservateur"},{"id":"b","label":"Agressif et probablement excessif"},{"id":"c","label":"Standard"},{"id":"d","label":"Interdit"}]'::jsonb, 'b', 'La croissance perpétuelle ne peut excéder la croissance économique long terme (2-4 %).', 'DcfSimulator', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ11', 'analyse-fondamentale', 'outils', 3, 'Le PeerComparisonMatrix peut révéler un « value trap » quand :', '[{"id":"a","label":"Le P/E est bas mais la croissance est négative et la dette élevée"},{"id":"b","label":"Le P/E est élevé"},{"id":"c","label":"L''entreprise est leader"},{"id":"d","label":"Le secteur est en expansion"}]'::jsonb, 'a', 'Multiple bas justifié par la dégradation = pas d''opportunité.', 'PeerComparisonMatrix', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ12', 'analyse-fondamentale', 'outils', 3, 'Pourquoi l''EarningsImpactEngine croise-t-il le beat/miss avec la guidance ?', '[{"id":"a","label":"Parce que la guidance oriente les attentes futures plus que le passé"},{"id":"b","label":"Parce que le passé n''a pas d''importance"},{"id":"c","label":"Parce que la guidance est obligatoire"},{"id":"d","label":"Parce que le beat est toujours positif"}]'::jsonb, 'a', 'Le marché est forward-looking. La guidance pilote le réajustement des modèles.', 'EarningsImpactEngine', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ1', 'analyse-fondamentale', 'previsions', 1, 'Le ForecastScenarioPlanner utilise :', '[{"id":"a","label":"Un seul scénario"},{"id":"b","label":"3 scénarios (optimiste, neutre, pessimiste) + probabilités"},{"id":"c","label":"10 scénarios identiques"},{"id":"d","label":"Aucun scénario"}]'::jsonb, 'b', 'La valeur espérée = Σ(probabilité × valorisation scénario).', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ2', 'analyse-fondamentale', 'previsions', 1, 'Dans le ScenarioBuilder, un scénario valide doit contenir :', '[{"id":"a","label":"Uniquement une thèse haussière"},{"id":"b","label":"Thèse + mécanisme + catalyseur + invalidation"},{"id":"c","label":"Un graphique technique"},{"id":"d","label":"Un ordre d''achat"}]'::jsonb, 'b', 'Scénario = pourquoi + comment + quand + sortie.', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ3', 'analyse-fondamentale', 'previsions', 1, 'La somme des probabilités des 3 scénarios dans le ForecastScenarioPlanner doit être :', '[{"id":"a","label":"50 %"},{"id":"b","label":"100 %"},{"id":"c","label":"150 %"},{"id":"d","label":"Variable"}]'::jsonb, 'b', 'C''est une distribution de probabilités complète.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ4', 'analyse-fondamentale', 'previsions', 2, 'Le ScenarioBuilder force à définir une « invalidation » car :', '[{"id":"a","label":"C''est une règle de l''AMF"},{"id":"b","label":"Sans invalidation = biais de confirmation, pas un vrai scénario"},{"id":"c","label":"Les stops sont obligatoires"},{"id":"d","label":"L''invalidation est optionnelle"}]'::jsonb, 'b', 'Définir la sortie avant l''entrée = discipline institutionnelle.', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ5', 'analyse-fondamentale', 'previsions', 2, 'Si la valeur espérée > cours actuel dans le ForecastScenarioPlanner, cela suggère :', '[{"id":"a","label":"Une asymétrie positive (upside)"},{"id":"b","label":"Une surévaluation"},{"id":"c","label":"Un scénario sans risque"},{"id":"d","label":"Une erreur de calcul"}]'::jsonb, 'a', 'L''asymétrie risque/rendement favorise l''achat.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ6', 'analyse-fondamentale', 'previsions', 2, 'Dans le ScenarioBuilder, le « catalyseur » correspond à :', '[{"id":"a","label":"Le moment précis où la thèse se déclenche"},{"id":"b","label":"La couleur du graphique"},{"id":"c","label":"Le dividende"},{"id":"d","label":"Le ratio D/E"}]'::jsonb, 'a', 'Quand = événement déclencheur (publication, décision politique).', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ7', 'analyse-fondamentale', 'previsions', 2, 'Pourquoi le ForecastScenarioPlanner exige-t-il 3 scénarios et non 1 ?', '[{"id":"a","label":"Parce que 1 scénario = absence de gestion du risque"},{"id":"b","label":"Parce que la loi l''exige"},{"id":"c","label":"Parce que les marchés sont prévisibles"},{"id":"d","label":"Parce que 3 est un chiffre magique"}]'::jsonb, 'a', 'La préparation multi-scénarios = anticipation des différents états du monde.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ8', 'analyse-fondamentale', 'previsions', 2, 'Dans le ScenarioBuilder, la « validation » d''un scénario correspond à :', '[{"id":"a","label":"L''acceptation par la banque centrale"},{"id":"b","label":"Les conditions confirmant que la thèse se matérialise"},{"id":"c","label":"Un algorithme"},{"id":"d","label":"Un consensus d''analystes"}]'::jsonb, 'b', 'C''est le miroir de l''invalidation : quand est-ce que je sais que j''ai raison ?', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ9', 'analyse-fondamentale', 'previsions', 3, 'Une probabilité de 70 % au scénario neutre et 15 % aux extrêmes dans le ForecastScenarioPlanner suggère :', '[{"id":"a","label":"Une confiance élevée dans le scénario central"},{"id":"b","label":"Une incertitude extrême"},{"id":"c","label":"Un marché efficient"},{"id":"d","label":"Une erreur de modélisation"}]'::jsonb, 'a', 'Distribution concentrée = faible volatilité attendue, scénario central dominant.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ10', 'analyse-fondamentale', 'previsions', 3, 'Pourquoi le ScenarioBuilder inclut-il une étape « export » du scénario ?', '[{"id":"a","label":"Pour le partager et le suivre dans un journal de trading"},{"id":"b","label":"Pour l''imprimer en couleur"},{"id":"c","label":"Parce que c''est obligatoire"},{"id":"d","label":"Pour le vendre"}]'::jsonb, 'a', 'L''export permet le suivi, la rétrospective et l''amélioration du processus décisionnel.', 'ScenarioBuilder', 'a9', true);
